using System;using System.IO;using System.Collections;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using Unity.XR.CoreUtils;using UnityEngine.Rendering;using LighthouseKeepers.WatchDemo;using LighthouseKeepers.Core.Progression;
public class CeilingCrawlProbe:MonoBehaviour{
 string folder;int failures;WatchDemoController w;NightmareScene scene;ScareKit kit;Transform head,body;Camera cam;Light helmet;RenderPipelineAsset previous;bool oldNightmare,changedNightmare;
 public static object Begin(string folder){EditorUtility.audioMasterMute=true;Directory.CreateDirectory(folder);var p=new GameObject("Ceiling crawl review").AddComponent<CeilingCrawlProbe>();p.folder=folder;p.StartCoroutine(p.Go());return true;}
 void Check(bool ok,string text){File.AppendAllText(folder+"/checks.txt",(ok?"PASS ":"FAIL ")+text+"\n");if(!ok)failures++;}
 T Field<T>(string n)=>(T)typeof(ScareKit).GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(kit);
 // The test turns its simulated Editor head toward the staged figure; runtime never moves a player's head.
 void Aim(){head.LookAt(body.TransformPoint(Vector3.up*.65f));}
 void Capture(string name){Aim();cam.transform.SetPositionAndRotation(head.position,head.rotation);var rt=new RenderTexture(1100,850,24);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1100,850,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1100,850),0,0);tex.Apply();File.WriteAllBytes(folder+"/"+name+".png",tex.EncodeToPNG());RenderTexture.active=null;cam.targetTexture=null;Destroy(tex);Destroy(rt);}
 void Advance(ScareSequenceState c,float target){while(c.Age+.1f<target)c.Tick(.1f,true,true,0,0);if(target>c.Age)c.Tick(target-c.Age,true,true,0,0);kit.Present(c,head.position);}
 IEnumerator Go(){
  w=FindAnyObjectByType<WatchDemoController>();scene=w.GetComponent<NightmareScene>();var rig=FindAnyObjectByType<XROrigin>();head=rig.Camera.transform;foreach(var b in rig.GetComponentsInChildren<Behaviour>(true))if(b.GetType().Name.Contains("TrackedPose")||b.GetType().Name.Contains("InputModality")||b.GetType().Name=="DesktopPreview")b.enabled=false;var cc=rig.GetComponent<CharacterController>();if(cc)cc.enabled=false;rig.MoveCameraToWorldLocation(new Vector3(-.4f,4.95f,-.6f));Physics.SyncTransforms();oldNightmare=HorrorTuning.Current.nightmareEnabled;changedNightmare=true;HorrorTuning.Current.nightmareEnabled=true;Check(scene.Begin(true),"Nightmare starts");scene.enabled=false;var c=w.State.Scare;for(int i=0;i<200&&c.Beat!=ScareBeat.Turn;i++)c.Tick(.1f,true,true,0,0);c.Place(HorrorTuning.Current.nightmareCorner,0);
  kit=(ScareKit)typeof(NightmareScene).GetField("kit",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(scene);kit.Beat(ScareBeat.Turn,0);kit.Present(c,head.position);body=GameObject.Find("Nightmare child").transform;var ceiling=Field<Vector3>("ceiling");var end=Field<Vector3>("ceilingEnd");float distance=Vector3.Distance(ceiling,end);Check(Field<bool>("turnHasWall")&&Field<bool>("turnHasCeiling"),"A real wall and ceiling were found");Check(distance>.2f&&distance<=HorrorTuning.Current.nightmareCeilingCrawlDistance+.01f,"Crawl moves along ceiling within its configured limit ("+distance.ToString("F2")+" m)");
  helmet=w.GetComponent<KeeperHeadlamps>().Lights.First(x=>x.transform.IsChildOf(head));Check(helmet.enabled,"Automatic helmet beam is active");cam=new GameObject("Crawl review camera").AddComponent<Camera>();cam.enabled=false;cam.fieldOfView=65;cam.nearClipPlane=.04f;previous=QualitySettings.renderPipeline;QualitySettings.renderPipeline=AssetDatabase.LoadAssetAtPath<RenderPipelineAsset>("Assets/_LighthouseKeepers/Settings/RenderPipeline/QuestPipeline.asset");yield return new WaitForSeconds(.3f);
  Advance(c,1.2f);yield return null;Capture("wall");Advance(c,2.8f);yield return null;Capture("ceiling-start");var start=body.position;Advance(c,3.8f);yield return null;Capture("ceiling-end");Check(Vector3.Distance(start,body.position)>.1f,"Body travels during the ceiling portion");Check(Vector3.Distance(head.position,body.GetComponent<Renderer>().bounds.ClosestPoint(head.position))>=.5f,"Rendered body stays outside face clearance");var renderer=body.GetComponent<Renderer>();kit.Present(c,renderer.bounds.center);Check(!renderer.enabled,"Body is hidden if a viewer moves inside its safety bounds");kit.Present(c,head.position);
  var cast=typeof(ScareKit).GetMethod("SafeCeilingEnd",BindingFlags.NonPublic|BindingFlags.Instance);var block=GameObject.CreatePrimitive(PrimitiveType.Cube);block.name="Temporary crawl obstacle";block.transform.position=ceiling+(end-ceiling).normalized*.40f-Vector3.up*.12f;block.transform.localScale=Vector3.one*.2f;Physics.SyncTransforms();var blocked=(Vector3)cast.Invoke(kit,new object[]{ceiling});Check(Vector3.Distance(ceiling,blocked)<distance-.1f,"A solid obstacle shortens the ceiling path");block.SetActive(false);Destroy(block);Physics.SyncTransforms();
  var far=new Vector3(200,200,200);var loneWall=GameObject.CreatePrimitive(PrimitiveType.Cube);loneWall.name="Temporary wall without a ceiling";loneWall.transform.position=far+new Vector3(.8f,.8f,0);loneWall.transform.localScale=new Vector3(.2f,2,2);Physics.SyncTransforms();var previousHead=head.position;c.Place(far,0);kit.Beat(ScareBeat.Turn,c.Age);kit.Present(c,head.position);Check(Field<bool>("turnHasWall")&&!Field<bool>("turnHasCeiling")&&Vector3.Distance(body.position,Field<Vector3>("wall"))<.01f,"A missing ceiling keeps the body upright at the wall");Check(head.position==previousHead,"Presentation never moves the player camera");loneWall.SetActive(false);Destroy(loneWall);Physics.SyncTransforms();c.Place(HorrorTuning.Current.nightmareCorner,0);kit.Beat(ScareBeat.Turn,c.Age);kit.Present(c,head.position);
  Check(ShaderUtil.GetShaderMessages(Shader.Find("Lighthouse/S5 Drowned oilskin")).All(x=>x.severity.ToString()!="Error"),"Quest-pipeline Editor shader has no errors");QualitySettings.renderPipeline=previous;File.WriteAllText(folder+"/result.json","{\"passed\":"+(failures==0?"true":"false")+",\"failures\":"+failures+"}");Destroy(cam.gameObject);Destroy(gameObject);
 }
 void OnDestroy(){if(changedNightmare&&HorrorTuning.Current)HorrorTuning.Current.nightmareEnabled=oldNightmare;}
}
